	eye : vec4f,
	// straight (unpremultiplied) fog colour (rgb; w reserved)
	fogColor : vec4f,
	// x = mode (0 off / 1 linear / 2 exp2), y = near, z = 1/(far - near),
	// w = density
	fogParams : vec4f,
	// xyz = height falloff x the world-up axis, in VIEW space;
	// w = exp(k * (cameraY - fogHeight)), pre-baked on the CPU
